"""Explain frozen original-validation input-sensitivity results."""
import collections,csv,hashlib,json
from pathlib import Path
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
ROOT=Path(__file__).resolve().parents[1];R=ROOT/'results/gate_validation_deletion'
def ci(v):
 a=np.asarray(v,np.float64);ix=np.random.default_rng(0).integers(0,len(a),(10000,len(a)));lo,hi=np.quantile(a[ix].mean(1),[.025,.975]);return dict(mean=float(a.mean()),low=float(lo),high=float(hi))
def main():
 status=json.loads((R/'status.json').read_text());N=R/'native_completed';out=N/'output'/f"job_{status['job']}";s=json.loads((out/'summary.json').read_text());a=json.loads((out/'independent_audit.json').read_text())
 assert a['summary_sha256']==hashlib.sha256((out/'summary.json').read_bytes()).hexdigest() and a['status']=='PASS_INDEPENDENT_FROZEN_VALIDATION_AUDIT'
 with (out/'paired_validation.csv').open() as f:rows=list(csv.DictReader(f))
 ids=sorted({r['pair'] for r in rows});assert len(ids)==96
 by=collections.defaultdict(list)
 for r in rows:by[(r['pair'],r['variant'])].append(r)
 fields=('feature_mse','task_error','common','contrast');standards={};conditions=('recent_only','full_history','privileged_small_budget','random_small_budget')
 for v in conditions:standards[v]={f:ci([np.mean([float(r[f]) for r in by[(p,v)]]) for p in ids]) for f in fields}
 groupstats={}
 for g in ('cue_oldest','cue_middle','cue_newest'):
  buckets=collections.defaultdict(list)
  for pair in ids:
   rr=[r for r in rows if r['pair']==pair and r['pool_group']==g]
   cr=[r for r in rr if not int(r['cue_present'])];keep=[r for r in rr if int(r['cue_present'])];non=[r for r in keep if not int(r['native_privileged'])];native=by[(pair,'privileged_small_budget')]
   assert len(cr)==6 and len(keep)==12 and len(native)==6 and len(non)==(6 if g=='cue_oldest' else 12)
   for f in fields:
    c=float(np.mean([float(r[f]) for r in cr]));k=float(np.mean([float(r[f]) for r in keep]));n=float(np.mean([float(r[f]) for r in non]));base=float(np.mean([float(r[f]) for r in native]));buckets['cue_delete_'+f].append(c);buckets['cue_keep_'+f].append(k);buckets['nonnative_'+f].append(n);buckets['penalty_'+f].append(n-base);buckets['deletion_delta_'+f].append(c-k)
  groupstats[g]={k:ci(v) for k,v in buckets.items()}
 diagnostic=s['by_pool_group'];counts={m:sum(v[m] for v in diagnostic.values()) for m in ('feature','task','both','cells')}
 output=dict(status='READABLE_VERIFIED_VALIDATION_DIAGNOSIS',original_conditions=standards,group_effects=groupstats,validation_numeric_condition_counts=counts,by_group_counts=diagnostic,physical_delete_input_identity=s['physical_delete_path_input_equal'],path_forward_maxdiff=s['max_path_forward_difference'],native_anchor_input_identity=s['native_privileged_anchor_input_equal'],anchor_forward_maxdiff=s['max_anchor_forward_difference'],prior_validation_maxdiff=s['max_prior_validation_MSE_difference'],true_target_decoder_correct=s['true_target_decoder_correct'],true_target_decoder_total=384,new_training=False,new_fitting=False,new_GPU=0,original_Phase1_GO=False)
 (R/'readable_results.json').write_text(json.dumps(output,indent=2)+'\n')
 plt.rcParams.update({'font.size':11,'axes.spines.top':False,'axes.spines.right':False})
 fig,axs=plt.subplots(1,2,figsize=(11,4.2));groups=list(groupstats);labels=['Cue oldest','Cue middle','Cue newest'];x=np.arange(3)
 for shift,key,color,lab in [(-.24,None,'.75','Original native 2-frame memory'),(0,'cue_keep_feature_mse','white','Keep cue; average two alternatives'),(.24,'cue_delete_feature_mse','.2','Delete cue')]:
  values=[standards['privileged_small_budget']['feature_mse']['mean']]*3 if key is None else [groupstats[g][key]['mean'] for g in groups]
  axs[0].bar(x+shift,values,.23,color=color,edgecolor='black',label=lab)
 axs[0].set(ylim=(0,.17),xticks=x,xticklabels=labels,ylabel='Future-feature MSE (lower is better)',title='A. Same scenes and 2-frame capacity');axs[0].legend(frameon=False,fontsize=8)
 axs[1].axhline(0,color='.5',lw=.8)
 for shift,key,marker,lab in [(-.12,'penalty_feature_mse','o','Total feature error'),(0,'penalty_common','s','Shared-part error'),(.12,'penalty_contrast','^','Future-contrast error')]:
  ds=[groupstats[g][key] for g in groups];v=np.array([d['mean'] for d in ds]);lo=np.array([d['low'] for d in ds]);hi=np.array([d['high'] for d in ds]);axs[1].errorbar(x+shift,v,yerr=[v-lo,hi-v],fmt=marker,color='black',markerfacecolor='white' if shift==0 else 'black',capsize=3,label=lab)
 axs[1].set(xticks=x,xticklabels=labels,ylabel='Extra error versus native context',title='B. Companion-frame penalty');axs[1].legend(frameon=False,fontsize=8)
 fig.text(.02,.015,'All panels use original validation pairs and frozen models. In B, positive means worse than the native 2-frame control.\nIntervals resample 96 base pairs after averaging seeds and horizons. Validation diagnosis does not replace original test acceptance.',fontsize=9)
 fig.tight_layout(rect=(0,.10,1,1));f=R/'figures';f.mkdir(exist_ok=True);fig.savefig(f/'validation_deletion.png',dpi=180,bbox_inches='tight');fig.savefig(f/'validation_deletion.pdf',bbox_inches='tight');plt.close(fig)
 stdtable='\n'.join(f"| {v} | {standards[v]['feature_mse']['mean']:.5f} | {100*standards[v]['task_error']['mean']:.2f}% |" for v in conditions)
 counttable='\n'.join(f"| {lab} | {diagnostic[g]['feature']}/6 | {diagnostic[g]['task']}/6 | {diagnostic[g]['both']}/6 |" for g,lab in zip(groups,labels))
 penaltytable='\n'.join(f"| {lab} | {groupstats[g]['penalty_feature_mse']['mean']:+.5f} [{groupstats[g]['penalty_feature_mse']['low']:+.5f}, {groupstats[g]['penalty_feature_mse']['high']:+.5f}] | {groupstats[g]['penalty_common']['mean']:+.5f} | {groupstats[g]['penalty_contrast']['mean']:+.5f} |" for g,lab in zip(groups,labels))
 harm=[g for g in groups if groupstats[g]['penalty_feature_mse']['low']>0];contrastbad=[g for g in groups if groupstats[g]['penalty_contrast']['low']>0];commonbad=[g for g in groups if groupstats[g]['penalty_common']['low']>0]
 decision=f"Novel cue-retaining contexts have a positive paired feature-error penalty in {len(harm)}/3 cue-position groups. Shared-part penalties are positive in {len(commonbad)}/3 and future-contrast penalties in {len(contrastbad)}/3."
 text=f'''# Gate: does the frozen predictor mishandle deletion inputs?\n\n18 October 2026. Original validation data only; no retraining, fitting, new encoding or GPU. No test forward, policy learning or fresh9137. Original gates and test outcomes remain unchanged.\n\n## Main result\n\n**There is no deletion-path packing discrepancy in the checked cases.** All **{s['physical_delete_path_input_equal']:,}** physical-delete/direct-pack inputs are bitwise identical; repeated forward outputs differ by **{s['max_path_forward_difference']:.1g}**. Thus this predictor cannot respond differently merely because the same two observations arrived through a deletion operation rather than direct packing. The scientific question is sensitivity to which two observations remain.\n\n{decision}\n\n## What was compared\n\nWe reused all96 original Gate validation base pairs (192 sibling episodes), three frozen seeds17/29/43 and horizons3/6. The same checkpoints, normalization, basis, decoder and encoded caches were checked. Every episode receives the original four validation contexts and nine age-counterbalanced deletion forks: three cue positions, three possible deletions. Each deletion fork keeps exactly two past frames plus the same four recent frames and legal actions. All14976 scalar outcomes and7488 paired rows are complete.\n\nThe original privileged two-frame condition retains the cue-start observation and the latest legal past observation. One cue-oldest deletion fork yields exactly that memory. All **{s['native_privileged_anchor_input_equal']}** such input anchors match exactly; maximum output difference across batch shapes is **{s['max_anchor_forward_difference']:.3g}**. Other cue-retaining forks change the companion observation while retaining capacity, scene, target, query and recent context.\n\nAll4608 prior alpha1 original-validation scalar errors were replayed, with maximum difference **{s['max_prior_validation_MSE_difference']:.3g}**. The true-feature decoder is correct on **{s['true_target_decoder_correct']}/384** actual validation targets; this is feature decoding, not forecast accuracy.\n\n## Original validation contexts\n\n| Original context | Feature MSE | Binary task error |\n|---|---:|---:|\n{stdtable}\n\nOnly privileged and random small-budget controls have the same two-frame past capacity as deletion forks. Full-history and recent-only rows are reference points with different capacities. No result here is a newly trained or selected model.\n\n![Frozen validation deletion diagnosis](../results/gate_validation_deletion/figures/validation_deletion.png)\n\n**Figure guide:** A compares errors on identical validation scenes. A higher bar is worse. B compares novel cue-retaining contexts with the original privileged two-frame control; zero means no extra error, and positive values mean the companion change hurts. The shared and contrast parts sum to full-feature error; neither is automatically background.\n\n## Does this already fail in validation?\n\n| Cue rank in the three-frame parent | Feature numeric conditions | Task numeric conditions | Both |\n|---|---:|---:|---:|\n{counttable}\n| All cue ranks | {counts['feature']}/18 | {counts['task']}/18 | {counts['both']}/18 |\n\nThese are **diagnostic validation checks**, each containing all96 base pairs; they use the original10% effect and strictly positive95% paired bootstrap lower bound (10000 resamples, seed0). They do not replace the registered128-pair test, change its denominator or turn validation findings into Phase1_GO. The prior actual test remains joint10/54 and seed-mean1/18.\n\n## Where the added error comes from\n\nThe following excludes the exact native-anchor fork and averages only novel cue-retaining companions within each group. Each difference is paired against the same scene's native privileged two-frame prediction.\n\n| Cue rank | Added feature error [95% CI] | Added shared-part error | Added future-contrast error |\n|---|---:|---:|---:|\n{penaltytable}\n\nIntervals average seeds and horizons within each base pair, then resample the96 base pairs. These are differences in the existing loss, not a new weighted acceptance metric. Original small-budget random sampling has positive logical support for each legal two-frame subset; we have not established that these histories are outside the training support. Actual training frequency and representation density were not measured.\n\n## Interpretation and repair boundary\n\nThe physical deletion implementation is not the identified problem: equal tensors yield equal outputs. Equal memory count alone is also insufficient to guarantee useful predictions. The measured paired context penalties identify any composition sensitivity without conflating it with scene difficulty or capacity. A claim that training-distribution shift uniquely causes the errors would go beyond this check.\n\n'''
 if harm:
  text+='The priority is the historical correction’s behavior on retained-frame combinations. Improving an average four-condition validation score does not certify all equal-capacity candidate sets. If a later repair is authorized, first align its validation objective with these fixed-capacity input patterns while preserving the original test and gates. Do not tune another global alpha on the revealed test.\n\n'
 else:
  text+='This validation check does not establish a consistent companion-induced feature penalty at the pooled level. The earlier test failures therefore require additional condition/generalization analysis rather than an assumed universal deletion-input defect. Do not claim the absence of an effect in every individual cell.\n\n'
 if contrastbad:
  text+='There is a future-contrast penalty as well as any shared distortion. A constant shared-offset subtraction cannot correct that contrast. The smallest legitimate next candidate would need to separate the common and contrast behavior of the frozen correction using training/validation data; simply shrinking or subtracting a common vector is not a demonstrated repair. No such candidate was fitted here. Without retraining, a complete Gate repair is not established by these data.\n\n'
 else:
  text+='The pooled results do not identify a consistently positive future-contrast penalty. A narrowly scoped, training-cache-only calibration of shared residual bias could be investigated before any network retraining, but scalar energies alone do not show that its vector direction is constant. No bias calibration was fitted, and this is not a claim it will pass.\n\n'
 geometry=json.loads((R/'transport_geometry.json').read_text())['transport_gain']
 table='\n'.join(f"| {g.replace('_',' ')} | {v['median']:.2f} | {v['p95']:.2f} | {v['maximum']:.2f} |" for g,v in geometry.items())
 text+='## A concrete mechanism to test next: temporal extrapolation\n\nThis explicitly post-hoc check uses the saved timestamps only. The frozen predictor forms a feature slope between the two historical observations and extrapolates it toward the future. Its structural multiplier is `(query - newer_timestamp + horizon) / historical_time_separation`. This is not a measured learned-branch norm.\n\n| Retained context | Median multiplier | 95th percentile | Maximum |\n|---|---:|---:|---:|\n'+table+'\n\nThe native two-frame context has a median multiplier of 1, while novel cue-retaining combinations have medians 7.5, 15 and 11.5. A short-lived cue change can therefore be subjected to much stronger linear extrapolation in the altered combinations. This is a plausible mechanism for the measured common and contrast distortions, but timestamp geometry alone does not prove which branch caused them: content and timestamps co-vary.\n\n**The next smallest falsifiable repair check is a Gate-only frozen transport-branch ablation on this same original validation set.** Compare the unchanged predictor with its transport contribution disabled at forward time, keeping its learned content branch, recent-only reference, weights, inputs and numeric criteria fixed. Do not retrain, tune a clipping grid on test, or modify Motion. If this ablation improves both shared and contrast errors without losing cue benefit, it supports targeting that branch; otherwise reject this mechanism as a sufficient fix. The ablation has not been executed or adopted here, and it may harm a co-adapted content branch. No repair or Phase1 pass is claimed.\n\n'
 text+='Original joint Gate-and-Motion policy readiness remains unsupported. Do not train a retention scorer to imitate unreliable Gate labels, waive a condition, replace full-feature loss with binary accuracy, or count these validation checks as independent confirmation.\n\n## Reproducibility and limits\n\nAn independent process verifies raw axes and sibling averages, original-validation replay, scalar intervals and fixed first-pair primitive vector witnesses. Weights, vectors and arrays stay HPC; compact files use native-before/local/native-after SHA256. Cue-time annotations construct diagnostic pools only; labels and future features never enter model tensors. Cue-start membership is used as an exact cue-presence label only for the constructed pools, which exclude the rest of the cue window; a random original memory can include another cue-window observation. Validation was previously used for checkpoint selection and is not fresh confirmation.\n\n[Protocol](../experiments/gate_validation_deletion/PROTOCOL.md), [native summary](../results/gate_validation_deletion/native_completed/output/job_JOB/summary.json), [independent audit](../results/gate_validation_deletion/native_completed/output/job_JOB/independent_audit.json), [readable data](../results/gate_validation_deletion/readable_results.json), and [transfer ledger](../results/gate_validation_deletion/native_completed/transfer_integrity.json). No GitHub update.\n'
 text=text.replace('job_JOB',f"job_{status['job']}")
 for a,b in [('all96','all 96'),('seeds17/29/43','seeds 17/29/43'),('horizons3/6','horizons 3/6'),('All14976','All 14,976'),('and7488','and 7,488'),('All4608','All 4,608'),('alpha1','alpha = 1'),('original10%','original 10%'),('positive95%','positive 95%'),('10000 resamples','10,000 resamples'),('seed0','seed 0'),('registered128','registered 128'),('joint10/54','joint 10/54'),('seed-mean1/18','seed-mean 1/18'),('the96','the 96'),('fresh9137','fresh 9137')]:text=text.replace(a,b)
 (ROOT/'docs/GATE_VALIDATION_DELETION.md').write_text(text);print(json.dumps(dict(decision=decision,counts=counts,report='docs/GATE_VALIDATION_DELETION.md')))
if __name__=='__main__':main()
